#include <cstddef>
#include <iostream>
#include <new>

struct Token {
  int value;
  int& destroyed;
  ~Token() { ++destroyed; }
};

int main() {
  int destroyed = 0;
  alignas(Token) std::byte storage[sizeof(Token)];
  Token* first = new (storage) Token{1, destroyed};
  first->~Token();
  Token* second = new (storage) Token{2, destroyed};
  std::cout << destroyed << second->value;
  second->~Token();
}
